function handleBrandUpload(input, type) {
  const file = input.files?.[0];
  if (!file) return;
  if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 500 * 1024) { toast('Usa PNG, JPG o WebP de máximo 500 KB.', true); input.value = ''; return; }
  const reader = new FileReader();
  reader.onload = () => {
    if (type === 'logo') { data.settings.logoData = reader.result; save(); render(); toast('Logo actualizado.'); return; }
    const image = new Image();
    image.onload = () => { const canvas = document.createElement('canvas'); canvas.width = 64; canvas.height = 64; const scale = Math.min(64 / image.width, 64 / image.height); const width = image.width * scale; const height = image.height * scale; canvas.getContext('2d').drawImage(image, (64 - width) / 2, (64 - height) / 2, width, height); data.settings.faviconData = canvas.toDataURL('image/png'); save(); render(); toast('Favicon actualizado.'); };
    image.onerror = () => toast('No se pudo leer la imagen seleccionada.', true);
    image.src = reader.result;
  };
  reader.onerror = () => toast('No se pudo leer el archivo.', true);
  reader.readAsDataURL(file);
  input.value = '';
}
